nderer>().sharedMaterial==mat&&root.GetComponentInChildren<MeshFilter>().sharedMesh==m,"prefab saved");var scene=Folder+"/reload.unity";EditorSceneManager.SaveScene(EditorSceneManager.GetActiveScene(),scene);EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);EditorSceneManager.OpenScene(scene);Check(UnityEngine.Object.FindObjectsByType<MeshRenderer>(FindObjectsSortMode.None).Any(r=>r.sharedMaterial==mat&&r.GetComponent<MeshFilter>().sharedMesh==m),"scene saved");
